'use client';

import { zodResolver } from '@hookform/resolvers/zod';
import { ArrowLeft, Save } from 'lucide-react';
import Link from 'next/link';
import { useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { toast } from 'sonner';
import { employeeSchema } from '@peopleos/types';
import { api } from '@/lib/api';
import { useDepartments } from '@/lib/queries';
import type { Employee } from '@peopleos/types';
import { Button, Card, FormField, Input, PageHeader, Select, Spinner } from './ui';

type FormValues = { firstName: string; lastName: string; email: string; phone?: string; department: string; designation: string; employmentType: 'FULL_TIME' | 'PART_TIME' | 'CONTRACT'; employmentStatus: 'ACTIVE' | 'ON_LEAVE' | 'INACTIVE' | 'TERMINATED'; joiningDate: string; managerName?: string; location?: string; baseSalary: number };
export function EmployeeForm({ employee }: { employee?: Employee }) { const edit = Boolean(employee); const departments = useDepartments(); const form = useForm<FormValues>({ resolver: zodResolver(employeeSchema), defaultValues: employee ? { firstName: employee.firstName, lastName: employee.lastName, email: employee.email, phone: employee.phone ?? '', department: employee.department, designation: employee.designation, employmentType: employee.employmentType, employmentStatus: employee.employmentStatus, joiningDate: employee.joiningDate.slice(0, 10), managerName: employee.managerName ?? '', location: employee.location ?? '', baseSalary: employee.baseSalary } : { employmentType: 'FULL_TIME', employmentStatus: 'ACTIVE', joiningDate: new Date().toISOString().slice(0, 10), baseSalary: 0 } }); useEffect(() => { if (employee) form.reset({ firstName: employee.firstName, lastName: employee.lastName, email: employee.email, phone: employee.phone ?? '', department: employee.department, designation: employee.designation, employmentType: employee.employmentType, employmentStatus: employee.employmentStatus, joiningDate: employee.joiningDate.slice(0, 10), managerName: employee.managerName ?? '', location: employee.location ?? '', baseSalary: employee.baseSalary }); }, [employee, form]); const submit = form.handleSubmit((values) => { const mutation = edit ? api.updateEmployee(employee!.id, values) : api.createEmployee(values); mutation.then(() => { toast.success(edit ? 'Employee updated' : 'Employee added'); window.location.href = '/admin/employees'; }).catch((error) => toast.error(error.message)); }); return <div><Link href="/admin/employees" className="mb-5 inline-flex items-center gap-2 text-xs font-bold text-[#777982] hover:text-[#ff725c]"><ArrowLeft className="h-4 w-4" />Back to employees</Link><PageHeader eyebrow={edit ? 'Edit people record' : 'New people record'} title={edit ? `${employee?.firstName} ${employee?.lastName}` : 'Add an employee'} description="Add the details your team needs to work well together." action={<Button onClick={submit} disabled={form.formState.isSubmitting}><Save className="h-4 w-4" />{form.formState.isSubmitting ? 'Saving…' : 'Save employee'}</Button>} /><form onSubmit={submit} className="grid gap-5 xl:grid-cols-[1.2fr_0.8fr]"><Card className="p-5 sm:p-7"><h2 className="mb-5 font-display text-xl">Personal details</h2><div className="grid gap-4 sm:grid-cols-2"><FormField label="First name *" error={form.formState.errors.firstName?.message}><Input {...form.register('firstName')} /></FormField><FormField label="Last name *" error={form.formState.errors.lastName?.message}><Input {...form.register('lastName')} /></FormField><FormField label="Work email *" error={form.formState.errors.email?.message}><Input type="email" {...form.register('email')} /></FormField><FormField label="Phone"><Input type="tel" {...form.register('phone')} /></FormField><FormField label="Location"><Input placeholder="Bengaluru" {...form.register('location')} /></FormField><FormField label="Manager"><Input placeholder="Manager name" {...form.register('managerName')} /></FormField></div></Card><Card className="p-5 sm:p-7"><h2 className="mb-5 font-display text-xl">Work details</h2><div className="space-y-4"><FormField label="Department *"><Select {...form.register('department')}><option value="">Choose department</option>{(departments.data ?? ['Engineering', 'Product', 'Design', 'Marketing', 'Finance', 'Human Resources']).map((item) => <option key={item}>{item}</option>)}</Select></FormField><FormField label="Designation *"><Input placeholder="e.g. Product Designer" {...form.register('designation')} /></FormField><FormField label="Employment type"><Select {...form.register('employmentType')}><option value="FULL_TIME">Full time</option><option value="PART_TIME">Part time</option><option value="CONTRACT">Contract</option></Select></FormField><FormField label="Status"><Select {...form.register('employmentStatus')}><option value="ACTIVE">Active</option><option value="ON_LEAVE">On leave</option><option value="INACTIVE">Inactive</option><option value="TERMINATED">Terminated</option></Select></FormField><FormField label="Joining date"><Input type="date" {...form.register('joiningDate')} /></FormField><FormField label="Annual base salary (INR)"><Input type="number" min="1" {...form.register('baseSalary', { valueAsNumber: true })} /></FormField></div></Card></form></div>; }
